CREATE FUNCTION public.media_job_terminal_outbox_list_unpublished_v1() RETURNS TABLE(media_job_public_id uuid, event_kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
