      FROM media_job_terminal_outbox outbox
      JOIN media_job job ON job.media_job_id = outbox.media_job_id
     WHERE outbox.published_at IS NULL
     ORDER BY outbox.created_at ASC, outbox.media_job_terminal_outbox_id ASC
     LIMIT 1024
