           t.name,
           t.state::TEXT,
           t.state_message,
           t.progress_bytes_downloaded,
           t.progress_bytes_total,
           t.progress_eta_seconds,
           t.download_bps,
           t.upload_bps,
           t.ratio,
           t.sequential,
           t.library_path,
